:root{
  --bg:#0f1220;
  --card:#171a2b;
  --ink:#e9ecff;
  --muted:#b7bce6;
  --line:#2a2f52;
  --accent:#8be9fd;
  --accent2:#ffd479;
  --bad:#ff6b6b;
  --good:#7CFFB2;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 600px at 20% 0%, #1b1f3a 0%, var(--bg) 55%);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 28px}
.hdr{display:flex;gap:14px;align-items:flex-end;justify-content:space-between;margin-bottom:14px}
h1{font-size:22px;margin:0 0 6px}
.sub{margin:0;color:var(--muted)}
.gr{font-family: ui-serif, "New Athena Unicode", "Noto Serif", "Times New Roman", serif; letter-spacing:0.2px}
.card{background:linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));border:1px solid var(--line);border-radius:14px;padding:14px 14px 12px;margin:12px 0;box-shadow:0 10px 30px rgba(0,0,0,0.25)}
.grid{display:grid;grid-template-columns:1.1fr 0.9fr;gap:14px}
@media (max-width:860px){.grid{grid-template-columns:1fr}}
label{display:block;color:var(--muted);margin:0 0 8px}
.row{display:flex;gap:10px;align-items:center}
input[type=text]{flex:1;min-width:220px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:#0c0f1c;color:var(--ink);outline:none}
input[type=text]:focus{border-color:#3a427a;box-shadow:0 0 0 3px rgba(139,233,253,0.12)}
button{padding:10px 12px;border-radius:12px;border:1px solid #3a427a;background:linear-gradient(180deg,#222a55,#1a2042);color:var(--ink);cursor:pointer}
button:hover{border-color:#5662b3}
button:active{transform:translateY(1px)}
button.ghost{background:transparent;border:1px dashed #3a427a;color:var(--muted)}
button.ghost:hover{border-style:solid;color:var(--ink)}
.opts{margin:12px 0 0;border:1px solid var(--line);border-radius:12px;padding:10px 10px 6px}
.opts legend{color:var(--muted);padding:0 6px}
.opt{display:block;margin:6px 0;color:var(--ink)}
.opt input{transform:translateY(1px);margin-right:8px}
.mini{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}
.out{border:1px solid var(--line);border-radius:12px;padding:12px;background:#0c0f1c}
.k{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:0.12em}
.big{font-size:34px;margin:6px 0 4px}
.explain{color:var(--muted)}
hr{border:none;border-top:1px solid var(--line);margin:12px 0}
.syll{font-size:18px;word-break:break-word}
.hint{color:var(--muted);font-size:12px;margin-top:6px}
.note{color:var(--ink)}
.note ul{margin:8px 0 0 18px}
.small{color:var(--muted);font-size:12px}
.ftr{margin-top:10px}
mark{background:rgba(255,212,121,0.18);color:var(--ink);padding:0 4px;border-radius:6px}
.bad{color:var(--bad)}
.good{color:var(--good)}
summary{cursor:pointer;color:var(--accent)}
summary:hover{color:var(--accent2)}

